<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');$pid=(int)($_GET['id']??0);require_selected_petugas($pid);$uid=(int)current_user()['id_user'];$q=$pdo->prepare('SELECT p.*,k.nama_kegiatan,k.tujuan_akhir,k.status status_kegiatan,k.tanggal_mulai,k.tanggal_selesai FROM petugas p JOIN kegiatan k ON k.id_kegiatan=p.id_kegiatan WHERE p.id_petugas=? AND p.id_user=? AND p.deleted_at IS NULL');$q->execute([$pid,$uid]);$p=$q->fetch();if(!$p){http_response_code(403);exit('Identitas petugas tidak valid untuk akun ini.');}$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$search=trim($_GET['q']??'');$sql="SELECT ph.id_progress,ph.tanggal,COUNT(DISTINCT dp.id_detail) jumlah_detail,GROUP_CONCAT(DISTINCT dp.desa ORDER BY dp.desa SEPARATOR ', ') desa,GROUP_CONCAT(DISTINCT dp.sls ORDER BY dp.sls SEPARATOR ', ') sls,MAX(kw.id_kwitansi) id_kwitansi,MAX(kw.nominal) kw_nominal,MAX(kw.keperluan) kw_keperluan,MAX(kw.nomor_surat_tugas) kw_nomor_st,MAX(kw.tanggal_surat_tugas) kw_tanggal_st,MAX(kw.berangkat) kw_berangkat,MAX(kw.bulan_pengajuan_kwitansi) kw_bulan,SUM(CASE WHEN dp.id_detail IS NOT NULL AND (dp.uraian_kegiatan IS NULL OR TRIM(dp.uraian_kegiatan)='' OR dp.output_tujuan IS NULL OR TRIM(dp.output_tujuan)='') THEN 1 ELSE 0 END) lpd_incomplete FROM progress_harian ph LEFT JOIN detail_progress dp ON dp.id_progress=ph.id_progress LEFT JOIN kwitansi kw ON kw.id_progress=ph.id_progress WHERE ph.id_petugas=?";$args=[$pid];if($from!==''){$sql.=' AND ph.tanggal>=?';$args[]=$from;}if($to!==''){$sql.=' AND ph.tanggal<=?';$args[]=$to;}if($search!==''){$sql.=' AND (dp.desa LIKE ? OR dp.sls LIKE ? OR ph.tanggal LIKE ?)';array_push($args,'%'.$search.'%','%'.$search.'%','%'.$search.'%');}$sql.=' GROUP BY ph.id_progress,ph.tanggal ORDER BY ph.tanggal DESC';$s=$pdo->prepare($sql);$s->execute($args);$history=$s->fetchAll();$hasLPD=in_array($p['tujuan_akhir'],['lpd','keduanya'],true);$hasKW=in_array($p['tujuan_akhir'],['kwitansi','keduanya'],true);page_header('Kelola Progress Harian');?>
<div class="card p-4 mb-3"><div class="d-flex justify-content-between flex-wrap"><div><div class="muted-label">Identitas Petugas</div><h2 class="h5 fw-bold mb-1"><?=e($p['nama_petugas'])?></h2><div class="text-secondary"><?=e($p['kecamatan'])?> · <?=e($p['nama_kegiatan'])?></div></div><a class="btn btn-light align-self-start" href="<?=APP_BASE_URL?>/petugas/dashboard.php">Kembali</a></div><div class="small text-secondary mt-2">Periode <?=format_tanggal($p['tanggal_mulai'])?> – <?=format_tanggal($p['tanggal_selesai'])?> · <?=e(tujuan_label($p['tujuan_akhir']))?></div></div>
<div class="card p-4 mb-3"><div class="d-flex justify-content-between align-items-center"><div><h2 class="h5 fw-bold mb-1">Input Data Progress Harian</h2><p class="small text-secondary mb-0">Satu progress per tanggal dapat berisi beberapa detail SLS.</p></div><?php if($hasLPD):?><a class="btn btn-outline-success" href="<?=APP_BASE_URL?>/petugas/dokumen/download_all_lpd.php?petugas_id=<?=$pid?>">Download Seluruh LPD (ZIP)</a><?php endif;?><?php if($p['status_kegiatan']==='aktif'):?><a class="btn btn-primary" href="<?=APP_BASE_URL?>/petugas/progress/form.php?petugas_id=<?=$pid?>">+ Input Progress Harian</a><?php else:?><span class="badge text-bg-secondary">Kegiatan Nonaktif · Hanya Lihat</span><?php endif;?></div></div>
<div class="card p-4"><div class="d-flex justify-content-between flex-wrap gap-2"><h2 class="h5 fw-bold">Riwayat Progress Harian</h2><form class="d-flex flex-wrap gap-2"><input type="hidden" name="id" value="<?=$pid?>"><input type="date" name="from" class="form-control form-control-sm" value="<?=e($from)?>"><input type="date" name="to" class="form-control form-control-sm" value="<?=e($to)?>"><input name="q" class="form-control form-control-sm" placeholder="Cari desa/SLS/tanggal" value="<?=e($search)?>"><button class="btn btn-sm btn-outline-primary">Filter</button></form></div><div class="table-responsive mt-3"><table class="table"><thead><tr><th>No</th><th>Hari/Tanggal</th><th>Jumlah Detail</th><th>Desa/Kelurahan</th><th>SLS</th><th>Aksi</th></tr></thead><tbody><?php foreach($history as $i=>$h):?><tr><td><?=$i+1?></td><td><?=e(date('l',strtotime($h['tanggal'])))?><br><?=format_tanggal($h['tanggal'])?></td><td><?=$h['jumlah_detail']?></td><td><?=e($h['desa']??'-')?></td><td><?=e($h['sls']??'-')?></td><td class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-secondary" href="<?=APP_BASE_URL?>/petugas/progress/view.php?petugas_id=<?=$pid?>&id=<?=$h['id_progress']?>">Lihat</a><?php if($p['status_kegiatan']==='aktif'):?><a class="btn btn-sm btn-outline-primary" href="<?=APP_BASE_URL?>/petugas/progress/form.php?petugas_id=<?=$pid?>&id=<?=$h['id_progress']?>">Edit</a><form method="post" action="<?=APP_BASE_URL?>/petugas/progress/delete.php" onsubmit="return confirm('Hapus progress tanggal ini beserta dokumentasinya?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="petugas_id" value="<?=$pid?>"><input type="hidden" name="id_progress" value="<?=$h['id_progress']?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif;?><?php if($hasLPD&&$h['jumlah_detail']&&(int)$h['lpd_incomplete']===0):?><a class="btn btn-sm btn-outline-success" href="<?=APP_BASE_URL?>/petugas/dokumen/download_lpd.php?petugas_id=<?=$pid?>&progress_id=<?=$h['id_progress']?>">LPD PDF</a><?php endif;?><?php $kwReady=$h['id_kwitansi']&&$h['kw_nominal']!==null&&trim((string)$h['kw_keperluan'])!==''&&trim((string)$h['kw_nomor_st'])!==''&&$h['kw_tanggal_st']&&$h['kw_berangkat']!==null&&trim((string)$h['kw_bulan'])!=='';?><?php if($hasKW&&$kwReady):?><a class="btn btn-sm btn-outline-success" href="<?=APP_BASE_URL?>/kwitansi_pdf_sipacak.php?id=<?=$h['id_kwitansi']?>">Kwitansi PDF</a><?php endif;?></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="6" class="text-center text-secondary py-4">Belum ada progress harian.</td></tr><?php endif;?></tbody></table></div></div><?php page_footer();
